#include <stdio.h>
#include <stdlib.h>

static int *head, *to, *next_edge;
static int *dist, *parent_node, *queue;
static int *stack_node, *stack_parent, *stack_depth;
static int edge_count;

static void add_edge(int u, int v) {
    to[edge_count] = v;
    next_edge[edge_count] = head[u];
    head[u] = edge_count++;
}

static int bfs(int start, int n, int save_parent) {
    for (int i = 0; i < n; i++) {
        dist[i] = -1;
        if (save_parent) parent_node[i] = -1;
    }

    int first = 0, last = 0;
    queue[last++] = start;
    dist[start] = 0;
    if (save_parent) parent_node[start] = start;

    int farthest = start;
    while (first < last) {
        int u = queue[first++];
        if (dist[u] > dist[farthest]) farthest = u;

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (save_parent) parent_node[v] = u;
                queue[last++] = v;
            }
        }
    }
    return farthest;
}

static long long count_at_depth(int root, int blocked, int target) {
    int top = 0;
    stack_node[top] = root;
    stack_parent[top] = blocked;
    stack_depth[top++] = 0;

    long long count = 0;
    while (top > 0) {
        --top;
        int u = stack_node[top];
        int p = stack_parent[top];
        int d = stack_depth[top];

        if (d == target) {
            count++;
            continue;
        }

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (v != p) {
                stack_node[top] = v;
                stack_parent[top] = u;
                stack_depth[top++] = d + 1;
            }
        }
    }
    return count;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    head = malloc((size_t)n * sizeof(int));
    to = malloc((size_t)(2 * (n - 1)) * sizeof(int));
    next_edge = malloc((size_t)(2 * (n - 1)) * sizeof(int));
    dist = malloc((size_t)n * sizeof(int));
    parent_node = malloc((size_t)n * sizeof(int));
    queue = malloc((size_t)n * sizeof(int));
    stack_node = malloc((size_t)n * sizeof(int));
    stack_parent = malloc((size_t)n * sizeof(int));
    stack_depth = malloc((size_t)n * sizeof(int));

    for (int i = 0; i < n; i++) head[i] = -1;

    for (int i = 0; i < n - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        add_edge(x - 1, y - 1);
        add_edge(y - 1, x - 1);
    }

    int a = bfs(0, n, 0);
    int b = bfs(a, n, 1);
    int diameter = dist[b];

    int *path = malloc((size_t)(diameter + 1) * sizeof(int));
    int path_len = 0;
    for (int v = b;; v = parent_node[v]) {
        path[path_len++] = v;
        if (v == a) break;
    }

    long long ways = 0;
    if (diameter % 2 == 0) {
        int center = path[diameter / 2];
        int radius = diameter / 2;
        long long total = 0, sum_squares = 0;

        for (int e = head[center]; e != -1; e = next_edge[e]) {
            int neighbor = to[e];
            long long count = count_at_depth(neighbor, center, radius - 1);
            total += count;
            sum_squares += count * count;
        }

        ways = (total * total - sum_squares) / 2;
    } else {
        int center1 = path[diameter / 2];
        int center2 = path[diameter / 2 + 1];
        int radius = diameter / 2;

        long long left_count = count_at_depth(center1, center2, radius);
        long long right_count = count_at_depth(center2, center1, radius);
        ways = left_count * right_count;
    }

    printf("%d\n%lld\n", diameter + 1, ways);

    free(path);
    free(head);
    free(to);
    free(next_edge);
    free(dist);
    free(parent_node);
    free(queue);
    free(stack_node);
    free(stack_parent);
    free(stack_depth);
    return 0;
}
